//! `indicators::Percentage`.

use super::cxx_fmt;

/// Formats a 0.0–1.0 fraction as a percentage with one decimal, e.g. `75.0%`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Percentage {
    value: f32,
}

impl Percentage {
    pub fn new(value: f32) -> Self {
        Percentage { value }
    }

    pub fn set_value(&mut self, value: f32) {
        self.value = value;
    }

    pub fn value(&self) -> f32 {
        self.value
    }

    /// Renders the percentage. Mirrors the C++ `str()` member: the `float` is
    /// widened to `double` before the multiply, then printed with
    /// `std::fixed` and a precision of one.
    pub fn str(&self) -> String {
        let mut s = cxx_fmt::fixed(self.value as f64 * 100.0, 1);
        s.push('%');
        s
    }
}

impl std::fmt::Display for Percentage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.str())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_the_cpp_test_program() {
        assert_eq!(Percentage::new(0.75).str(), "75.0%");
    }

    #[test]
    fn common_fractions() {
        assert_eq!(Percentage::new(0.0).str(), "0.0%");
        assert_eq!(Percentage::new(1.0).str(), "100.0%");
        assert_eq!(Percentage::new(0.5).str(), "50.0%");
        assert_eq!(Percentage::new(0.125).str(), "12.5%");
    }
}

